-- 99: migration 2900 (release 47): photo standard r48.1. Every car's nine standard angles generated by Gemini from
-- references (the car's real photos, or its check-in and check-out photos when it has too few), the job's order (the front
-- three-quarter of every car first), the retries with feedback, the flag, the plates, the gallery, and that no real photo is
-- taken off the site. Fixtures start with "rq48_"; no real names or plates.
select test.suite('99 r47 photo standard r48 (2900)');

create temp table rq48_prev as select listing_showroom_ai as ai, listing_showroom_ai_daily as daily, listing_photo_r48_auto as auto, listing_photo_r45_auto as r45auto,
  listing_photo_r45_reserve as reserve, listing_photo_r45_batch as batch from app.settings();
update program_settings set listing_showroom_ai = true, listing_photo_r48_auto = true, listing_photo_r45_auto = false, listing_photo_r45_batch = 200,
       listing_photo_r45_reserve = 0, listing_showroom_ai_daily = 20000
 where id = (select id from app.settings());
-- the queue starts empty for this file
update listing_jobs set status = 'succeeded', finished_at = now() where kind = 'photo_r45' and status in ('queued', 'running');

select test.mk_user('rq48_admin', 'admin');
select test.mk_user('rq48_fleet', 'va', 'fleet');
select test.mk_owner('rq48_olive');
select test.mk_vehicle('rq48_a', 'rq48_olive');   -- listing photos: front three-quarter, rear, dashboard
select test.mk_vehicle('rq48_h', 'rq48_olive');   -- no listing photo: check-in photos only
select test.mk_vehicle('rq48_c', 'rq48_olive');   -- one inside listing photo and check-in photos

select test.eq('the standard is the web''s R48_SPEC', app.photo_r48_spec(), 'r48.1');
select test.ok('the r48 run is on by default; the r45 fleet remake off',
  (select column_default from information_schema.columns where table_name = 'program_settings' and column_name = 'listing_photo_r48_auto') = 'true'
  and (select column_default from information_schema.columns where table_name = 'program_settings' and column_name = 'listing_photo_r45_auto') = 'false');

create temp table rq48_i as select
  (app.start_listing_intake(test.id('rq48_admin'), jsonb_build_object('vehicle_id', test.id('vehicle:rq48_a'))) ->> 'intake_id')::uuid as a,
  (app.start_listing_intake(test.id('rq48_admin'), jsonb_build_object('vehicle_id', test.id('vehicle:rq48_c'))) ->> 'intake_id')::uuid as c;
create or replace function test.rq48_up(p_intake uuid, p_shot text) returns uuid language sql as $$
  select (app.record_listing_upload(test.id('rq48_admin'), p_intake, jsonb_build_object('shot_type', p_shot,
          'original_path', 'vehicles/original/rq48/' || p_shot || '-' || md5(random()::text) || '.jpg', 'width', 3000, 'height', 2000, 'byte_size', 900000, 'mime_type', 'image/jpeg')) ->> 'photo_id')::uuid $$;
create or replace function test.rq48_live(p_car text) returns void language sql as $$
  update vehicle_photos set background_status = 'done', status = 'approved', is_public = true, plate_status = 'not_visible', preset_version = 'gemini_r45',
         processed_path = coalesce(processed_path, 'vehicles/rq48/' || p_car || '-' || shot_type || '-' || left(id::text, 6) || '.jpg')
   where vehicle_id = test.id('vehicle:' || p_car) and replaced_at is null and not r48;
  update listing_jobs set status = 'succeeded', finished_at = now() where vehicle_id = test.id('vehicle:' || p_car) and status in ('queued', 'running') $$;
create or replace function test.rq48_row(p_car text, p_shot text) returns vehicle_photos language sql as $$
  select * from vehicle_photos where vehicle_id = test.id('vehicle:' || p_car) and r48 and shot_type = p_shot and replaced_at is null order by created_at desc limit 1 $$;
create or replace function test.rq48_job(p_photo uuid) returns listing_jobs language sql as $$
  select * from listing_jobs where vehicle_photo_id = p_photo and kind = 'photo_r45' order by created_at desc limit 1 $$;
create or replace function test.rq48_answer(p_photo uuid, p jsonb) returns jsonb language plpgsql as $$
declare v uuid := (test.rq48_job(p_photo)).id;
begin
  update listing_jobs set status = 'running', attempts = attempts + 1, locked_at = now(), locked_by = 'rq48', started_at = now() where id = v;
  return app.worker_listing_result(v, p);
end $$;
create or replace function test.rq48_made(p_path text, p_extra jsonb default '{}'::jsonb) returns jsonb language sql as $$
  select jsonb_build_object('ok', true, 'provider', 'ai', 'output', jsonb_build_object('processed_path', p_path, 'width', 1800, 'height', 1200,
    'variants', '[]'::jsonb, 'preset_version', 'gemini_r48', 'flags', '[]'::jsonb, 'showroom', jsonb_build_object('provider', 'ai', 'mode', 'r48', 'spec', 'r48.1'),
    'r45', jsonb_build_object('pass', true, 'spec', 'r48.1', 'generated', true, 'plates', '[]'::jsonb, 'model', 'gemini-2.5-flash-image', 'check_model', 'gemini:gemini-2.5-flash',
      'view', 'front_left', 'reasons', '[]'::jsonb) || p_extra)) $$;
create or replace function test.rq48_refused(p_reasons jsonb) returns jsonb language sql as $$
  select jsonb_build_object('ok', true, 'provider', 'gemini', 'output', jsonb_build_object('r45', jsonb_build_object('pass', false, 'spec', 'r48.1', 'generated', true,
    'why', 'the check refused it', 'reasons', p_reasons))) $$;

create temp table rq48_ap as select test.rq48_up((select a from rq48_i), 'front_left') as fl, test.rq48_up((select a from rq48_i), 'rear') as rear,
  test.rq48_up((select a from rq48_i), 'dashboard') as dash;
select test.rq48_up((select c from rq48_i), 'dashboard');
select test.rq48_live('rq48_a');
select test.rq48_live('rq48_c');
-- check-in photos (a baseline report: no booking needed), with close-ups, keys and a licence that are never references
insert into condition_reports (id, vehicle_id, kind) values (test.id('cr:rq48_h'), test.id('vehicle:rq48_h'), 'baseline'), (test.id('cr:rq48_c'), test.id('vehicle:rq48_c'), 'baseline');
insert into condition_report_photos (condition_report_id, seq, shot, storage_path)
select test.id('cr:rq48_' || c), row_number() over (partition by c), s, 'reports/rq48/' || c || '/' || s || '.jpg'
  from unnest(array['h', 'c']) c cross join unnest(array['keys', 'licence', 'rear', 'front_left', 'left', 'roof']) s;

-- ---------------------------------------------------------------- 1. the references
select test.ok('a car with listing photos: its own photos only, the same angle first',
  (select e -> 0 ->> 'shot' = 'front_left' and jsonb_array_length(e) = 3 and not exists (select 1 from jsonb_array_elements(e) x where x ->> 'from' <> 'listing' or x ->> 'bucket' <> 'vehicle-originals')
     from (select app.photo_r48_refs(test.id('vehicle:rq48_a'), 'front_left') e) t));
select test.ok('a car with no listing photo: its check-in photos, the same angle first, no keys, licence or roof',
  (select e -> 0 ->> 'shot' = 'front_left' and jsonb_array_length(e) = 3 and bool_and(x ->> 'from' = 'handover' and x ->> 'bucket' = 'condition-photos')
          and bool_and(x ->> 'shot' in ('front_left', 'rear', 'left'))
     from (select app.photo_r48_refs(test.id('vehicle:rq48_h'), 'front_left') e) t, jsonb_array_elements(e) x group by e));
select test.ok('too few listing photos (one, inside only): its listing photo first, then the check-in photos fill up',
  (select e -> 0 ->> 'from' = 'listing' and (select count(*) from jsonb_array_elements(e) x where x ->> 'from' = 'handover') = 3
     from (select app.photo_r48_refs(test.id('vehicle:rq48_c'), 'rear') e) t));

-- ---------------------------------------------------------------- 2. the job: the front three-quarter of every car first
update program_settings set listing_photo_r45_batch = least(200, greatest(1, (select count(*) from app.photo_r48_cars() c where jsonb_array_length(app.photo_r48_refs(c.vehicle_id, 'front_left')) > 0)::integer))
 where id = (select id from app.settings());
create temp table rq48_run1 as select app.job_photo_r48() as msg, (select listing_photo_r45_batch from app.settings()) as room;
select test.ok('with room for one view a car, every car gets its front three-quarter first',
  (select count(*) > 0 and bool_and(ph.shot_type = 'front_left') from listing_jobs j join vehicle_photos ph on ph.id = j.vehicle_photo_id where j.kind = 'photo_r45' and j.status = 'queued')
  and (test.rq48_row('rq48_a', 'front_left')).id is not null and (test.rq48_row('rq48_h', 'front_left')).id is not null and (test.rq48_row('rq48_c', 'front_left')).id is not null,
  (select msg || ', room ' || room from rq48_run1) || '; queued: ' || coalesce((select string_agg(ph.shot_type || '/' || coalesce(v.fleet_number, left(v.id::text, 4)), ',') from listing_jobs j join vehicle_photos ph on ph.id = j.vehicle_photo_id
     join vehicles v on v.id = ph.vehicle_id where j.kind = 'photo_r45' and j.status = 'queued'), 'none'));
update program_settings set listing_photo_r45_batch = 200 where id = (select id from app.settings());
select app.job_photo_r48();
select test.eq('then the other eight angles of the car, in the site''s order (the front three-quarter sorted first)',
  (select string_agg(shot_type, ',' order by sort_order) from vehicle_photos where vehicle_id = test.id('vehicle:rq48_a') and r48 and replaced_at is null),
  'front_left,front,left,rear_left,rear,dashboard,front_seats,rear_seats,trunk');
select test.ok('each r48 view: ai_generated, off the site until it passes, one job photo_r45 in mode r48 with the car named',
  (select count(*) = 9 and bool_and(ph.ai_generated and not ph.is_public and ph.status = 'processing' and j.input #>> '{r45,mode}' = 'r48' and j.input #>> '{r45,car,make}' is not null)
     from vehicle_photos ph join listing_jobs j on j.vehicle_photo_id = ph.id and j.kind = 'photo_r45' and j.status = 'queued'
    where ph.vehicle_id = test.id('vehicle:rq48_a') and ph.r48));
select app.job_photo_r48();
select test.eq('again: nothing new (one view an angle)', (select count(*)::text from vehicle_photos where vehicle_id = test.id('vehicle:rq48_a') and r48), '9');
update listing_jobs set status = 'cancelled', finished_at = now() where vehicle_photo_id = (test.rq48_row('rq48_c', 'trunk')).id and status = 'queued';
select app.photo_r48_queue(null, test.id('vehicle:rq48_c'), 'trunk');
select test.ok('a view whose step was lost (cancelled) is queued again, the same row',
  (test.rq48_job((test.rq48_row('rq48_c', 'trunk')).id)).status = 'queued' and (select count(*) = 1 from vehicle_photos where vehicle_id = test.id('vehicle:rq48_c') and r48 and shot_type = 'trunk'));
select test.ok('the r45 machinery leaves the r48 views alone', not exists (select 1 from vehicle_photos ph where ph.r48 and app.photo_r45_applies(ph)));

-- a car photographed only at handovers: a listing to run on (not published), and its check-in photos never become listing photos
select test.ok('handover-only car: a listing made for the job, approved, not published',
  (select count(*) = 1 and bool_and(state = 'approved') from listing_intakes where vehicle_id = test.id('vehicle:rq48_h')));
select test.ok('its check-in photos are never a listing photo nor on the site: only its r48 views exist, off the site until passed',
  not exists (select 1 from vehicle_photos where vehicle_id = test.id('vehicle:rq48_h') and (not r48 or is_public or original_path like 'reports/%')));

-- ---------------------------------------------------------------- 3. the worker's context
create temp table rq48_ctx as select app.listing_job_context((test.rq48_job((test.rq48_row('rq48_h', 'front_left')).id)).id) as x;
select test.ok('context: the references fresh (check-in photos for this car), the family, the guide, the body; no plate yet',
  (select x #>> '{input,r45,family}' = 'front' and x #>> '{input,r45,guide}' like 'site/r48/guides/%-lead.jpg' and x #> '{input,r45,refs,0}' ->> 'bucket' = 'condition-photos'
          and x #>> '{input,r45,plate}' is null and x #>> '{input,r45,body}' is not null from rq48_ctx));
select test.ok('an inside angle: no family and no stock photo',
  (select x #>> '{input,r45,family}' is null and x #>> '{input,r45,stock}' is null
     from (select app.listing_job_context((test.rq48_job((test.rq48_row('rq48_a', 'dashboard')).id)).id) as x) t));

-- ---------------------------------------------------------------- 4. the plates
select test.rq48_answer((test.rq48_row('rq48_h', 'front_left')).id, test.rq48_made('vehicles/rq48/h-fl-r48.jpg',
  jsonb_build_object('plate_made', jsonb_build_object('family', 'front', 'path', 'site/r48/plates/front-aa11.jpg', 'model', 'gemini-2.5-flash-image', 'check', jsonb_build_object('pass', true, 'issues', '[]'::jsonb)))));
select test.ok('a plate the worker made is kept for the family (Gemini, its check)',
  (select source = 'gemini' and path = 'site/r48/plates/front-aa11.jpg' and "check" ->> 'pass' = 'true' from listing_r48_plates where family = 'front'));
select test.eq('the next view of the family is sent it',
  app.listing_job_context((test.rq48_job((test.rq48_row('rq48_a', 'front_left')).id)).id) #>> '{input,r45,plate}', 'site/r48/plates/front-aa11.jpg');
select test.rq48_answer((test.rq48_row('rq48_c', 'front_left')).id, test.rq48_made('vehicles/rq48/c-fl-r48.jpg',
  jsonb_build_object('plate_made', jsonb_build_object('family', 'front', 'path', 'site/r48/plates/front-bb22.jpg'))));
select test.eq('a second plate made at the same time does not replace the first', (select path from listing_r48_plates where family = 'front'), 'site/r48/plates/front-aa11.jpg');
select test.throws('fleet staff do not set the plates', format('select app.photo_r48_plates(%L, %L)', test.id('rq48_fleet'), '{"family":"all","path":"site/r48/plates/admin-all-1a2b.jpg"}'), '%Admin%');
select test.throws('a plate path outside site/r48/plates is refused', format('select app.photo_r48_plates(%L, %L)', test.id('rq48_admin'), '{"family":"side","path":"vehicles/x.jpg"}'), '%not valid%');
select app.photo_r48_plates(test.id('rq48_admin'), '{"family":"all","path":"site/r48/plates/admin-all-1a2b.jpg"}');
select test.ok('an Admin''s real showroom photo replaces the plates of every outside family',
  (select count(*) = 3 and bool_and(source = 'admin' and path = 'site/r48/plates/admin-all-1a2b.jpg') from listing_r48_plates));
select app.photo_r48_plates(test.id('rq48_admin'), '{"family":"side","clear":true}');
select test.eq('Make a new one: the side plate taken off (Gemini makes it with the next side view)', (select string_agg(family, ',' order by family) from listing_r48_plates), 'front,rear');

-- ---------------------------------------------------------------- 5. passed: on the site in place of the real photo of the angle; the real one stays
select test.rq48_answer((test.rq48_row('rq48_a', 'front_left')).id, test.rq48_made('vehicles/rq48/a-fl-r48.jpg'));
select test.ok('passed: approved, public, done, marked ai_generated',
  (select status = 'approved' and is_public and ai_generated and r45 ->> 'state' = 'done' and processed_path = 'vehicles/rq48/a-fl-r48.jpg' from test.rq48_row('rq48_a', 'front_left')));
select test.eq('the gallery leads with the r48 front three-quarter', app.public_listing_photos(test.id('vehicle:rq48_a')) -> 0 ->> 'path', 'vehicles/rq48/a-fl-r48.jpg');
select test.ok('the real front three-quarter is not shown beside it (one photo an angle)',
  not exists (select 1 from jsonb_array_elements(app.public_listing_photos(test.id('vehicle:rq48_a'))) e where e ->> 'shot' = 'front_left' and e ->> 'path' <> 'vehicles/rq48/a-fl-r48.jpg'));
select test.ok('the angles without an r48 view still show the real photos (rear, dashboard)',
  (select count(*) = 2 from jsonb_array_elements(app.public_listing_photos(test.id('vehicle:rq48_a'))) e where e ->> 'shot' in ('rear', 'dashboard')));
select test.eq('the cover is the r48 front three-quarter', (app.cover_photo(test.id('vehicle:rq48_a'))).id::text, (test.rq48_row('rq48_a', 'front_left')).id::text);
select test.ok('no real photo is hidden: every real photo of the car is still approved and public, in its record',
  (select count(*) = 3 and bool_and(is_public and status = 'approved' and replaced_at is null) from vehicle_photos where vehicle_id = test.id('vehicle:rq48_a') and not ai_generated));
select test.rq48_up((select a from rq48_i), 'front_left');
select test.ok('a new real photo of the angle does not replace the r48 view', (select replaced_at is null and is_public from test.rq48_row('rq48_a', 'front_left')));

-- ---------------------------------------------------------------- 6. refused: again with feedback, then flagged; the real photo stays
create temp table rq48_rr as select (test.rq48_row('rq48_a', 'rear')).id as id;
select test.rq48_answer((select id from rq48_rr), test.rq48_refused('["looks_cgi"]'));
select test.ok('refused once: queued again, the try counted',
  (select r45 ->> 'state' = 'queued' and (r45 ->> 'tries')::int = 1 from vehicle_photos where id = (select id from rq48_rr)) and (test.rq48_job((select id from rq48_rr))).status = 'queued');
select test.eq('the next try is told why', app.listing_job_context((test.rq48_job((select id from rq48_rr))).id) #>> '{input,r45,feedback}', '["looks_cgi"]');
select test.rq48_answer((select id from rq48_rr), test.rq48_refused('["wrong_wheels"]'));
select test.rq48_answer((select id from rq48_rr), test.rq48_refused('["wrong_framing"]'));
select test.ok('refused three times: flagged, off the site, no job left',
  (select r45 ->> 'state' = 'flagged' and not is_public and quality_flags ? 'r45_flagged' from vehicle_photos where id = (select id from rq48_rr))
  and not exists (select 1 from listing_jobs where vehicle_photo_id = (select id from rq48_rr) and status = 'queued'));
select test.ok('the real rear photo stays on the site and in the gallery',
  (select is_public and status = 'approved' from vehicle_photos where id = (select rear from rq48_ap))
  and exists (select 1 from jsonb_array_elements(app.public_listing_photos(test.id('vehicle:rq48_a'))) e where e ->> 'shot' = 'rear'));
select app.job_photo_r48();
select test.ok('a flagged view is not made again by itself', not exists (select 1 from listing_jobs where vehicle_photo_id = (select id from rq48_rr) and status = 'queued'));

-- ---------------------------------------------------------------- 7. Admin: the card and the redo
create temp table rq48_view as select app.photo_r45_fleet_read(test.id('rq48_fleet')) as v;
select test.ok('the card: per car its r48 set (done, flagged, of nine), a handover-only car listed too, the r48 run on',
  (select (c #>> '{r48,done}')::int = 1 and (c #>> '{r48,flagged}')::int = 1 and (c #>> '{r48,angles}')::int = 9 from rq48_view, jsonb_array_elements(v -> 'cars') c where c ->> 'id' = test.id('vehicle:rq48_a')::text)
  and (select (c #>> '{r48,handover_refs}')::boolean from rq48_view, jsonb_array_elements(v -> 'cars') c where c ->> 'id' = test.id('vehicle:rq48_h')::text)
  and (select (v ->> 'r48_auto')::boolean and v ->> 'r48_spec' = 'r48.1' from rq48_view));
create temp table rq48_redo as select app.photo_r45_redo(test.id('rq48_fleet'), jsonb_build_object('vehicle', test.id('vehicle:rq48_a'))) as r;
select test.ok('Redo this car now: the flagged and the done views queued again, the done one stays on the site meanwhile',
  (select (r ->> 'r48')::int >= 2 from rq48_redo)
  and (select r45 ->> 'state' = 'queued' and is_public from test.rq48_row('rq48_a', 'front_left'))
  and (select r45 ->> 'state' = 'queued' and (r45 ->> 'tries')::int = 0 and not quality_flags ? 'r45_flagged' from vehicle_photos where id = (select id from rq48_rr)));
create temp table rq48_all as select app.photo_r45_redo(test.id('rq48_admin'), jsonb_build_object('all', true)) as r;
select test.ok('Redo every car marks the r48 views to be made again', (select r ? 'r48_waiting' from rq48_all));

-- ---------------------------------------------------------------- 8. off
update program_settings set listing_photo_r48_auto = false where id = (select id from app.settings());
select test.eq('switched off in Program settings: the job does nothing', app.job_photo_r48(), 'off');

update program_settings set listing_showroom_ai = p.ai, listing_showroom_ai_daily = p.daily, listing_photo_r48_auto = p.auto, listing_photo_r45_auto = p.r45auto,
       listing_photo_r45_reserve = p.reserve, listing_photo_r45_batch = p.batch
  from rq48_prev p where program_settings.id = (select id from app.settings());
